<h1 class="h3 mb-4"><?= $user ? 'Editar administrador' : 'Novo administrador' ?></h1><form method="post" action="/usuarios/salvar" class="card card-body bg-white"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><?php if ($user): ?><input type="hidden" name="id" value="<?= (int) $user['id'] ?>"><?php endif; ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome</label><input class="form-control" name="nome" maxlength="150" required value="<?= htmlspecialchars($user['nome'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-6"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email" maxlength="190" required value="<?= htmlspecialchars($user['email'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-6"><label class="form-label">Senha <?= $user ? '(deixe em branco para manter)' : '' ?></label><input class="form-control" type="password" name="password" minlength="12" <?= $user ? '' : 'required' ?>></div><?php if ($user): ?><div class="col-12"><label><input type="checkbox" name="ativo" <?= $user['ativo'] ? 'checked' : '' ?>> Ativo</label></div><?php endif; ?></div><div class="mt-4"><button class="btn btn-primary">Salvar</button> <a class="btn btn-outline-secondary" href="/usuarios">Cancelar</a></div></form>
